/*! tailwindcss v4.3.0 | MIT License | https://tailwindcss.com */
.color-input[data-v-55dadc03] {
  border-color: var(--input);
  transition: border-color var(--duration-fast) var(--ease-standard),
        box-shadow var(--duration-fast) var(--ease-standard);
  --input-action-width: 2.5rem;
  mask-image: linear-gradient(to right, black calc(100% - var(--input-action-width)), transparent 100%);
  -webkit-mask-image: linear-gradient(to right, black calc(100% - var(--input-action-width)), transparent 100%);
}
.color-input[data-v-55dadc03]:focus {
  mask-image: none;
  -webkit-mask-image: none;
}
.color-input-error[data-v-55dadc03] {
  box-shadow: 0 0 0 2px var(--destructive);
@supports (color: color-mix(in lab, red, red)) {
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--destructive) 25%, transparent);
}
}
.color-input-mode-flash[data-v-55dadc03] {
  animation: input-mode-flash-55dadc03 var(--duration-slow) var(--ease-decelerate);
}
@keyframes input-mode-flash-55dadc03 {
0% {
    transform: scaleX(0.97);
    opacity: 0.6;
}
100% {
    transform: scaleX(1);
    opacity: 1;
}
}
.color-input:empty[data-placeholder][data-v-55dadc03]::before {
  content: attr(data-placeholder);
  color: var(--muted-foreground);
  pointer-events: none;
}
.send-btn[data-v-55dadc03] {
  position: absolute;
  right: 0.25rem;
  top: 50%;
  transform: translateY(-50%);
  padding: 0.25rem;
  border-radius: var(--radius-sm);
  cursor: pointer;
}
.send-btn[data-v-55dadc03]:disabled {
  cursor: not-allowed;
}
.error-badge[data-v-55dadc03] {
  position: absolute;
  right: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  font-size: var(--text-xs, 0.75rem);
  line-height: var(--tw-leading, var(--text-xs--line-height, calc(1 / 0.75)));
  line-height: 1;
  padding: 0.2rem 0.4rem;
  border-radius: var(--radius-sm);
  background: var(--destructive);
  color: var(--destructive-foreground);
  white-space: nowrap;
  pointer-events: none;
  font-family: var(--font-sans);
  --vj-celebrate-y: -50%;
  --vj-celebrate-scale: 0.85;
}
@keyframes crown-appear-55dadc03 {
0% {
    opacity: 0;
    color: var(--color-gold-light);
    transform: scale(0) rotate(-15deg);
}
40% {
    opacity: 1;
    color: var(--color-gold);
    transform: scale(1.4) rotate(5deg);
    filter: drop-shadow(0 0 6px color-mix(in srgb, var(--color-gold) 70%, transparent));
}
70% {
    color: var(--color-gold);
    transform: scale(0.95) rotate(-2deg);
    filter: drop-shadow(0 0 3px color-mix(in srgb, var(--color-gold) 40%, transparent));
}
100% {
    color: var(--color-gold);
    transform: scale(1) rotate(0deg);
    filter: none;
}
}

/* `.gold-shimmer-icon` lives in @styles/utils.css (S.W7-7 — the byte-identical
 * scoped twin this file carried is retired; ONE global recipe, god-module
 * census §2.1). */

/* W7-4 — the BOUNDED view-switch hue sweep (the W3-7 §2 mechanism, form A):
 * the <color>-registered `--accent-view` transitions on THIS trigger scope
 * only — the icon + ring inherit the one animating computed value, so the
 * navigation still SWEEPS to the new view's hue, while the root token snaps
 * (no per-frame whole-document inherited-property invalidation — the P1-7
 * tax is dead). PRM: neutralised by the global guard like any transition. */
.view-select-trigger[data-v-f4747a24] {
    transition: --accent-view var(--duration-panel) var(--ease-standard);
}

/* The machine-truth detail line threads the certified de-emphasis rung
 * (`--ink-muted` — boot-stamped, floor-clamped against the live resting plate;
 * the same rung EmptyState's error `detail` rides), so this new surface adds NO
 * sub-floor contrast debt (the U-F26 error-detail contrast lane is coordinated,
 * not double-cured here). */
.plate-ink[data-v-97dc6261] {
    color: var(--ink-muted, var(--muted-foreground));
}

/* Fonts loaded via <link> tags in index.html to avoid render-blocking @import */

/* Project-specific font aliases */

.fraunces {
    font-family: var(--font-display);
    font-optical-sizing: auto;
}

.fira-code {
    font-family: var(--font-mono);
}

/* Shared single-line caption recipe — `.section-label` (glass-ui typography)
 * extended with muted half-opacity and a one-line clamp. Consumed by the
 * control-bar components (gradient / mix / generate). The standard `line-clamp`
 * drives modern engines; `-webkit-line-clamp` + `-webkit-box` remain the
 * Safari support floor. */

.section-subtitle {
    font-family: var(--font-mono);
    font-size: var(--type-caption);
    color: color-mix(in srgb, var(--muted-foreground) 50%, transparent);
    overflow: hidden;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 1;
    line-clamp: 1;
}

/* `.pastel-rainbow-text` EXCISED (S.W5-7 · Q4 RATIFIED EXCISE 2026-07-05;
 * the `--accent-live` ramp alternative NOT taken): the fixed six-hue candy
 * ramp failed contrast at every stop over the light header wash (≈1.1–1.5:1),
 * ignored the per-view accent axis, and was the page's only rainbow moment —
 * decoration, not information. The three consumers (PalettesPane heading,
 * DockViewSelect palettes entry, PaletteDialog header) speak ink. */

/* The ONE loading-ink recipe (S.W5 Lane A / W5-1 — the `ec1b200` register,
 * modernized): every skeleton surface in the app reads this single muted-ink
 * family through glass-ui's `--skeleton-glass-bg` seam — one `color-mix`,
 * both schemes, opaque enough to read as SHADOW against the field, never as
 * content. The `--skeleton-shimmer-tint` line is the letter-L9 producer seam
 * (the sheen joins the same ink family once glass-ui's `::after` reads it).
 * Consumers: ShadowPalette + PaletteCardSkeleton (both `bg-well`),
 * AdminListSkeleton + the admin tag-chip shadows (resting plate).
 *
 * E1-R2 (T.W8 remediation_1): the former `color-mix(muted-foreground 22%,
 * muted)` recipe was NOT certified against its ground — in dark it landed ≈
 * `--well-bg` (probed ΔL 0.007, seg-vs-well 1.02:1), collapsing the ghost to a
 * featureless slab. The ink is now a CERTIFIED tone-step OF the well ground
 * itself: a fixed φ-ish fraction of `--foreground` mixed into `--well-bg`, so
 * the block is guaranteed a bounded ΔL from the well in BOTH schemes by
 * construction (darker than the well in light, lifted above it in dark — the
 * scheme-adaptive direction falls out of the token, no per-scheme fork), and
 * the genesis "muted blocks" read as BLOCKS against every neutral skeleton
 * ground (well ≈ resting plate). Low-chroma by construction (both `--well-bg`
 * and `--foreground` are near-neutral), so the muted-family character holds. */

.skeleton-ink-register {
    --skeleton-ink: color-mix(in oklab, var(--well-bg), var(--foreground) 15%);
    --skeleton-glass-bg: var(--skeleton-ink);
    --skeleton-shimmer-tint: color-mix(in srgb, var(--muted-foreground) 24%, transparent);
}

/* The SPECIMEN ink walk (S.W5-1's `specimen` register, FINALLY consumed —
 * T.W3-2 · D9): a low-chroma hue rotation around the live accent (fixed 36°
 * steps, C clamped to 0.12) mixed INTO the ink base so the ghost stays
 * shadow-first, per-segment via `--i`. Lifted here from PaletteCardSkeleton's
 * scoped block the day it gained a second consumer (DESIGN.md's
 * global-utility rule): the ShadowPalette true-empty ghost (STILL) reads it
 * as fill; the developing skeleton's strip seams read it through glass-ui's
 * `--skeleton-glass-bg`. Guarded: engines without relative-color calc() keep
 * the plain ink base (the recipe never falls to transparent). */

.specimen-seg {
    --specimen-ink: var(--skeleton-ink);
}

@supports (color: oklch(from red calc(l) c calc(h + 36deg))) {
    .specimen-seg {
        --specimen-ink: color-mix(
            in oklab,
            var(--skeleton-ink) 78%,
            oklch(from var(--accent-live) l 0.12 calc(h + var(--i, 0) * 36deg))
        );
    }
}

/* Dashed inset well — the recessed container that collects an in-progress set
 * of colors (the mix "Selected" tray, the current-palette editor). Both sites
 * used `.dashed-well` as a never-defined phantom (inv-N-7); this mints the
 * intended affordance in house tokens: a dashed-bordered, faintly-recessed
 * column that visually groups its swatch row + label, echoing the dashed
 * add-swatch button each well already contains. */

.dashed-well {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
    padding: 0.75rem;
    /* R.W4 Lane A / A1 — hairline law 4: the well's dashed edge reads the ONE
     * `--card-edge` mint (in-house, scheme-stable), never a `--border` fork. */
    border: 1.5px dashed var(--card-edge);
    border-radius: var(--radius-card);
    /* T.W3-1 (D1 rung-2 WELL; supersedes the S-20 glass recipe — R8): an
     * in-plate fixture is an opaque TONE-STEP of its host plate, never a
     * second pane of glass — the ONE `--well-bg` token, NO backdrop-blur
     * (blurring the aurora through the host is the mud generator, RC-3).
     * The dashed edge ALONE carries the in-progress semantics; the chip
     * cartoon rung stays. */
    background: var(--well-bg);
    box-shadow: var(--shadow-cartoon-sm);
}

/* THE SEATED SEARCH FIELD (T.W3-3 · T-12 — THE REGISTER LAW: fields on paper
 * wear paper; fields on glass stay glass). glass-ui's `.input-bar` recipe is
 * dock furniture — the FLOATING chrome rung (80/88%-α glass + blur(13px) +
 * a 24rem dock cap + a baked mono voice). Seated in a pane BODY it is the one
 * floating-glass element in a cartoon-grammar column (t-search-tabs §1-3):
 * over a flat plate the blur has nothing to blur, the dark roast reads darker
 * than its own plate, and the cap rags the bar 78px short of its siblings at
 * 1440 AND 768 (t-mobile F-7). This opt-in re-seats the bar on the MATERIAL
 * LADDER as the Z2 in-plate fixture it is (DESIGN.md § Surfaces):
 *
 *   fill    — the ONE rung-2 `--well-bg` tone-step, NO backdrop-blur (RC-3);
 *   edge    — the drawn `--card-edge` ink hairline (the dashed-well's solid
 *             sibling — hairline law 4, ONE edge mint);
 *   stamp   — `--shadow-cartoon-sm`, the chip-scale elevation PaletteCard rides;
 *   measure — the dock cap dies: a seated field runs its host column (ASK-C);
 *   voice   — content-class (the `.input-bar-field` rule below).
 *
 * INTERIM DEMO SEAT — a consumer opt-in on the producer recipe (unlayered, so
 * it wins over the `@layer components` recipe by layer order — the exact
 * mechanism the producer's own `bare` rung proved), NEVER a recipe fork.
 * BOOKED SWAP (T.W3 §BOOKS "W3-3 interim search seat"): dies onto glass-ui's
 * P3 seated field-chrome rung — GLASSUI-T-ASKS ASK-D (`variant="seated"`),
 * with ASK-B (the font seam) + ASK-C (the cap seam) — at the adopt event. */

.search-seated {
    background: var(--well-bg);
    backdrop-filter: none;
    border: 1.5px solid var(--card-edge);
    box-shadow: var(--shadow-cartoon-sm);
    max-width: none;
}

/* Compose, never replace: the producer's focus ring joins the stamp (the
 * unlayered base box-shadow above would otherwise silently beat the layered
 * `.input-bar:focus-within` ring). */

.search-seated:focus-within {
    box-shadow: var(--shadow-cartoon-sm), var(--focus-ring-shadow);
}

/* Voice = CONTENT-CLASS (T-12): a prose search field speaks its plate's text
 * voice; the producer's baked `--font-mono` (`components.css:235`, ASK-B's
 * seam target) is a statement about CSS-literal readouts, not prose. Mono
 * stays an EXPLICIT per-field opt-in (SearchFilterBar's color input keeps it
 * by class; identifier fields opt back in the same way). */

.search-seated .input-bar-field {
    font-family: inherit;
}

/* The gold ADMIN-identity icon ink (S.W7-1 consume / W7-7 dedup home) — the
 * ONE demo-side gold icon recipe, lifted here because its consumers span
 * components (the Dock.vue wax-seal ink + DockViewSelect's trigger/menu
 * icons; scoped copies were byte-identical twins, god-module census §2.1).
 * The fuller "ONE gold/admin shimmer primitive" consolidation stays the
 * filed glass-ui letter L15 ask. */

.gold-shimmer-icon {
    color: var(--color-gold);
    filter: drop-shadow(0 0 2px color-mix(in srgb, var(--color-gold) 30%, transparent));
}

/* Swatch-row list idiom (R.W4 Lane B / B1) — shared by the three swatch
 * TransitionGroups (CurrentPaletteEditor, MixSourceSelector,
 * MixResultDisplay): dots pop in/out on the enter/exit family with
 * scale-only geometry, neighbours reflow on the family move class, and the
 * leaving dot is lifted out of flow so the row closes smoothly. A shared
 * recipe (3 consumers) per DESIGN.md's global-utility rule. */

.swatch-row {
    --vj-enter-y: 0px;
    --vj-enter-scale: 0;
}

.swatch-row > .vj-enter-leave-active {
    position: absolute;
}

/* THE GUARDED LETTERFORM RAMP recipe (T.W6 · W6-4 — Q5 RULED, owner-verbatim:
 * "Only palettes should be rainbow--the letterforms dropdown and the title";
 * T-43 owner-CONFIRMS). The ONE recipe for the exactly-TWO consume sites
 * (DockViewSelect's "Palettes" entry + PalettesPane's title letterforms) —
 * never a scoped twin (the S.W7-7 lesson). Stops are the THREE root tokens
 * `boot/useViewAccents` writes from the ONE resolver
 * (`@composables/color/palettes-ramp` — derived from the live accent,
 * gamut-guarded, WCAG ≥4.5:1 text-floor); the guard's output IS O-14's T-10
 * referent. C3-ledger: the sanctioned exception to the nav ink law (Q18).
 * Fallbacks = the resolver's own pre-first-write class of value (the
 * `--accent-view` @property initial family), overwritten at first resolve. */

.palettes-ramp-text {
    background-image: linear-gradient(
        90deg,
        var(--palettes-ramp-0, oklch(0.632 0.214 333.5)),
        var(--palettes-ramp-1, oklch(0.632 0.214 13.5)),
        var(--palettes-ramp-2, oklch(0.632 0.214 53.5))
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

